pub struct Counter {
    value: i64,
    initial: i64,
    step: i64,
}

impl Counter {
    pub fn new(initial: i64, step: i64) -> Self {
        Counter { value: initial, initial, step }
    }

    pub fn increment(&mut self) {
        self.value -= self.step; // BUG 1: should be +=
    }

    pub fn decrement(&mut self) {
        self.value -= self.step;
    }

    pub fn reset(&mut self) {
        self.value = self.step; // BUG 2: should be self.initial
    }

    pub fn value(&self) -> i64 {
        self.value * 2 // BUG 3: should be self.value
    }
}

