use counter::Counter;

#[test]
fn test_increment() {
    let mut c = Counter::new(0, 1);
    c.increment();
    c.increment();
    c.increment();
    assert_eq!(c.value(), 3);
}

#[test]
fn test_decrement() {
    let mut c = Counter::new(10, 2);
    c.decrement();
    assert_eq!(c.value(), 8);
}

#[test]
fn test_reset() {
    let mut c = Counter::new(5, 1);
    c.increment();
    c.increment();
    c.reset();
    assert_eq!(c.value(), 5);
}
